<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Concerns\ResolvesVendor; use App\Http\Controllers\Controller; use App\Models\Addon; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request;
class AddonController extends Controller { use ResolvesVendor; private function out(Addon $a): array{return ['id'=>(string)$a->id,'name'=>$a->name,'price'=>(float)$a->price,'active'=>$a->is_active];} public function index(): JsonResponse{return response()->json($this->resolveVendor()->addons()->orderByDesc('is_active')->orderBy('name')->get()->map(fn($a)=>$this->out($a))->values());} public function store(Request $r): JsonResponse{$v=$r->validate(['name'=>['required','string','min:2','max:100'],'price'=>['required','numeric','min:0'],'active'=>['sometimes','boolean']]);$a=$this->resolveVendor()->addons()->create(['name'=>$v['name'],'price'=>$v['price'],'is_active'=>$r->boolean('active',true)]);return response()->json($this->out($a),201);} public function update(Request $r, Addon $addon): JsonResponse{$this->own($addon);$v=$r->validate(['name'=>['sometimes','string','min:2','max:100'],'price'=>['sometimes','numeric','min:0'],'active'=>['sometimes','boolean']]);$addon->fill(['name'=>$v['name']??$addon->name,'price'=>$v['price']??$addon->price,'is_active'=>array_key_exists('active',$v)?$v['active']:$addon->is_active])->save();return response()->json($this->out($addon));} public function destroy(Addon $addon): JsonResponse{$this->own($addon);$addon->delete();return response()->json(null,204);} private function own(Addon $a):void{if($a->vendor_id!==$this->resolveVendor()->id)abort(404);} }
